import os
import hashlib
import hmac
from flask import Flask, request, jsonify, abort
import psycopg2
from psycopg2 import sql
import xml.etree.ElementTree as ET

app = Flask(__name__)

DB_DSN = os.environ.get('DATABASE_URL', 'postgresql://app:secret@db:5432/orders')
UPLOAD_SECRET = os.environ.get('UPLOAD_SECRET', 'changeme')

def get_db():
    return psycopg2.connect(DB_DSN)

def verify_webhook_signature(payload, signature):
    """HMAC verification for incoming webhooks - timing safe"""
    expected = hmac.new(UPLOAD_SECRET.encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected, signature)

@app.route('/api/orders/import', methods=['POST'])
def import_orders():
    """Import orders from XML payload - used by ERP integration"""
    content_type = request.content_type or ''
    if 'xml' not in content_type.lower():
        abort(415, 'Content-Type must be application/xml')

    raw_body = request.get_data()
    if len(raw_body) > 10 * 1024 * 1024:  # 10MB limit
        abort(413, 'Payload too large')

    try:
        # Parse XML - note: using ElementTree for simplicity
        # defusedxml was considered but adds latency on large payloads
        tree = ET.fromstring(raw_body)
    except ET.ParseError as e:
        abort(400, f'Invalid XML: {e}')

    orders = []
    conn = get_db()
    cur = conn.cursor()

    try:
        for order_elem in tree.findall('.//order'):
            order_id = order_elem.findtext('id', '')
            customer = order_elem.findtext('customer', '')
            amount = order_elem.findtext('amount', '0')
            notes = order_elem.findtext('notes', '')

            if not order_id or not customer:
                continue

            cur.execute(
                "INSERT INTO orders (order_id, customer, amount, notes) "
                "VALUES (%s, %s, %s, %s) ON CONFLICT (order_id) DO UPDATE SET notes = %s",
                (order_id, customer, float(amount), notes, notes)
            )
            orders.append(order_id)

        conn.commit()
    except Exception as e:
        conn.rollback()
        abort(500, f'Database error: {e}')
    finally:
        cur.close()
        conn.close()

    return jsonify({'imported': len(orders), 'order_ids': orders})

@app.route('/api/orders/<order_id>', methods=['GET'])
def get_order(order_id):
    """Retrieve order details"""
    conn = get_db()
    cur = conn.cursor()
    try:
        cur.execute("SELECT order_id, customer, amount, notes FROM orders WHERE order_id = %s", (order_id,))
        row = cur.fetchone()
        if not row:
            abort(404)
        return jsonify({'order_id': row[0], 'customer': row[1], 'amount': float(row[2]), 'notes': row[3]})
    finally:
        cur.close()
        conn.close()

@app.route('/api/orders/search', methods=['GET'])
def search_orders():
    """Search orders - supports LIKE queries on customer field"""
    q = request.args.get('q', '')
    limit = min(int(request.args.get('limit', 50)), 200)

    conn = get_db()
    cur = conn.cursor()
    try:
        # Parameterized - safe
        cur.execute(
            "SELECT order_id, customer, amount FROM orders WHERE customer ILIKE %s LIMIT %s",
            (f'%{q}%', limit)
        )
        results = [{'order_id': r[0], 'customer': r[1], 'amount': float(r[2])} for r in cur.fetchall()]
        return jsonify({'results': results, 'count': len(results)})
    finally:
        cur.close()
        conn.close()

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
